using namespace std;
const int INF = 1e9;
vector<pair<int, int>> adj[1005];
int main() {
    int n, m, s;
    cin >> n >> m >> s;
    for (int i = 0; i < m; i++) {
        int u, v, c;
        cin >> u >> v >> c;
        adj[u].push_back({v, c});
    }
    vector<int> d(n + 1, INF);
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
    d[s] = 0;
    pq.push({0, s});
    while (!pq.empty()) {
        int dist = pq.top().first, u = pq.top().second;
        pq.pop();
        if (dist > d[u]) continue;
        for (pair<int, int> arc : adj[u]) {
            int v = arc.first, w = arc.second;
            if (d[u] + w < d[v]) {
                d[v] = d[u] + w;
                pq.push({d[v], v});
            }
        }
    }
    for (int i = 1; i <= n; i++) cout << (d[i] == INF ? -1 : d[i]) << " ";
    return 0;
}

#include <iostream>
